          calls: [{ n: "GrammarProviderDescriptor / GrammarProviderCapability", d: T("Describen id, tecnología, versión y capacidades declaradas (analizar, generar, LSP, worker de navegador…)", "Describe id, technology, version and declared capabilities (analyse, generate, LSP, browser worker…)") }],
